// Bundles the skill's reference files into lib/knowledge.generated.ts so the
// app does not need to read files outside web/ at runtime. The generated file
// is committed; if the references are not present (e.g. only web/ was
// deployed) the committed copy is kept.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const refs = path.join(here, "..", "..", "references");
const out = path.join(here, "..", "lib", "knowledge.generated.ts");
const files = [
  "scoring_criteria.md",
  "sensitive_words.md",
  "multi_site_adaptation.md",
  "amazon_listing_rules_2025.md",
  "cosmo_rufus_optimization.md",
  "aleo_buyer_qa.md",
];

if (!fs.existsSync(refs)) {
  console.log("references/ not found; keeping committed knowledge file");
  process.exit(0);
}
const body = files
  .map((f) => `<reference file="${f}">\n${fs.readFileSync(path.join(refs, f), "utf8").trim()}\n</reference>`)
  .join("\n\n");
fs.writeFileSync(
  out,
  `// Generated by scripts/build-knowledge.mjs from ../references. Do not edit.\nexport const KNOWLEDGE = ${JSON.stringify(body)};\n`,
);
console.log(`knowledge: ${files.length} files, ${body.length} chars`);
